//! The generated "Export formats" reference page (`cargo run -p xtask -- gen-docs`).

use std::fmt::Write as _;

use crate::{registry, OptKind, Requires};

pub const REFERENCE_DOC_PATH: &str = "site/src/content/docs/docs/reference/export-formats.md";

fn cell(s: &str) -> String {
    s.replace('|', "\\|")
}

pub fn reference_markdown() -> String {
    let mut out = String::from(
        "---\ntitle: Export formats\ndescription: Every recording export format with its options, ranges and defaults.\n---\n\n\
         <!-- Generated by `cargo run -p xtask -- gen-docs` from the `mt_export` registry. Do not edit. -->\n\n\
         How exports work: [Exporting recordings](/docs/exporting-recordings/). Pass options with \
         `--opt KEY=VALUE`; defaults for some come from `[recording.export]`.\n",
    );
    for e in registry() {
        let _ = write!(out, "\n## `{}` — {}\n\n", e.id(), e.label());
        let _ = write!(out, "Default extension: `.{}`.", e.extension());
        if e.requires().contains(Requires::INPUT) {
            out.push_str(" Needs a recording made with input (`capture_input` or `--input`).");
        }
        out.push_str("\n\n| Option | Type | Default | Description |\n|---|---|---|---|\n");
        for o in e.options() {
            let ty = match &o.kind {
                OptKind::Bool => "bool".to_string(),
                OptKind::Int { min, max } => format!("int {min}–{max}"),
                OptKind::Float { min, max } => format!("float {min}–{max}"),
                OptKind::Enum(v) => v.join(" \\| "),
                OptKind::Text => "text".to_string(),
            };
            let _ = writeln!(
                out,
                "| `{}` | {} | `{}` | {} |",
                o.key,
                ty,
                cell(&o.default.to_string()),
                cell(o.help)
            );
        }
    }
    out
}
